| 1 | 7.5% | 1.25% | 0.25% | 0.1% | 0.01% | 0.01% |
| 2 | 6.5% | 1.75% | 0.75% | 0.5% | 0.05% | 0.01% |
| 3 | 3.5% | 2.75% | 1.25% | 1.0% | 0.1% | 0.01% |
| 4 | 2.0% | 3.50% | 2.25% | 1.5% | 1.00% | 0.01% |
| 5 | 1.5% | 3.75% | 2.50% | 2.0% | 1.00% | 0.01% |
| 6 | 1.0% | 3.25% | 3.75% | 2.5% | 1.5% | 0.05% |
