SELECT
	'users' AS table_name,
	COUNT(*) AS row_count
FROM users
WHERE id = '00000000-0000-0000-0000-000000000001'

UNION ALL

SELECT
	'wiki_pages',
	COUNT(*)
FROM wiki_pages

UNION ALL

SELECT
	'wiki_revisions',
	COUNT(*)
FROM wiki_revisions

UNION ALL

SELECT
	'published_pages',
	COUNT(*)
FROM wiki_pages
WHERE published_revision_id IS NOT NULL;
